/**
 * Checks if an avatar URL is auto-generated (Google OAuth, UI Avatars, Gravatar, etc.)
 * These look bad when used as hero/cover images since they're just initials or generic icons.
 *
 * @param {string} url - Avatar URL to check
 * @returns {boolean} True if the URL is an auto-generated avatar
 */
export const isAutoGeneratedAvatar = (url) => {
  if (!url || typeof url !== 'string') return true;

  const autoGeneratedPatterns = [
    'googleusercontent.com',
    'ui-avatars.com',
    'gravatar.com',
    'dicebear.com',
    'robohash.org',
    'placeholder.com',
    'default_avatar',
  ];

  const lowerUrl = url.toLowerCase();
  return autoGeneratedPatterns.some(pattern => lowerUrl.includes(pattern));
};
